WITH events AS (SELECT event_time,event_type,table_uuid,table,part_name,rows,bytes_uncompressed,size_in_bytes,merged_from FROM clusterAllReplicas(default,merge('system','^part_log'))
 WHERE event_date BETWEEN '2026-08-08' AND '2026-08-09' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-09 19:40:58','UTC')
 AND table_uuid IN (toUUID('7d9eac64-dbb9-4c43-8275-b70fd2b7c3ee'),toUUID('51ef6752-cdc7-4d90-bd20-b295dfbd561e')) AND event_type IN ('NewPart','MergeParts') AND error=0) SELECT toJSONString(groupArray(tuple(table,parts,rows,uncompressed_bytes,part_size_bytes))) AS payload FROM (SELECT table,count() AS parts,sum(rows) AS rows,sum(bytes_uncompressed) AS uncompressed_bytes,sum(size_in_bytes) AS part_size_bytes FROM events WHERE tuple(table_uuid,part_name) GLOBAL NOT IN (SELECT tuple(table_uuid,arrayJoin(merged_from)) FROM events WHERE event_type='MergeParts') GROUP BY table ORDER BY table LIMIT 10) LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=5000000,max_memory_usage=1500000000,skip_unavailable_shards=1;
